// The C++ compose() must reproduce the Studio's composeIcon() byte-for-byte.
// Golden vectors: tests/fixtures/rvhl-golden/compose.json, generated by
// `scripts/export_rvhl.sh --golden` from the Studio's own TypeScript.
#include <gtest/gtest.h>

#include <filesystem>
#include <fstream>

#include <nlohmann/json.hpp>

#include "roados/rvhl/Rvhl.h"

using namespace roados;
using namespace roados::rvhl;
using nlohmann::json;
namespace fs = std::filesystem;

namespace {

json readJson(const fs::path& p) {
    std::ifstream in(p);
    return json::parse(in);
}

HazardOptions toOptions(const json& o) {
    HazardOptions h;
    if (o.contains("variant")) h.variant = o["variant"].get<std::string>();
    if (o.contains("severity")) h.severity = parseSeverity(o["severity"].get<std::string>());
    if (o.contains("theme")) h.theme = *parseTheme(o["theme"].get<std::string>());
    if (o.contains("representation")) {
        const auto r = o["representation"].get<std::string>();
        h.representation = r == "standard" ? Representation::Standard : r == "roados" ? Representation::RoadOS : Representation::Auto;
    }
    if (o.contains("showSeverityCode")) h.showSeverityCode = o["showSeverityCode"].get<bool>();
    if (o.contains("count")) h.count = o["count"].get<int>();
    if (o.contains("distanceM")) h.distanceM = o["distanceM"].get<double>();
    if (o.contains("unitSystem")) h.unitSystem = o["unitSystem"] == "imperial" ? UnitSystem::Imperial : UnitSystem::Metric;
    if (o.contains("direction")) {
        const auto d = o["direction"].get<std::string>();
        h.direction = d == "left" ? Direction::Left : d == "right" ? Direction::Right : d == "both" ? Direction::Both : Direction::Ahead;
    }
    if (o.contains("lane")) h.lane = Lane{o["lane"]["count"].get<int>(), o["lane"]["index"].get<int>()};
    if (o.contains("sizeVariant")) {
        const auto s = o["sizeVariant"].get<std::string>();
        h.sizeVariant = s == "S" ? SizeVariant::S : s == "M" ? SizeVariant::M : s == "L" ? SizeVariant::L : SizeVariant::XL;
    }
    if (o.contains("background")) h.background = *Color::parse(o["background"].get<std::string>());
    if (o.contains("speed")) {
        const auto& s = o["speed"];
        SpeedBadge b;
        const auto k = s["kind"].get<std::string>();
        b.kind = k == "posted" ? SpeedBadge::Kind::Posted : k == "advisory" ? SpeedBadge::Kind::Advisory : SpeedBadge::Kind::Unknown;
        if (!s["valueKmh"].is_null()) b.valueKmh = s["valueKmh"].get<double>();
        b.unit = s["unit"] == "mph" ? SpeedUnit::Mph : SpeedUnit::Kmh;
        h.speed = b;
    }
    return h;
}

}  // namespace

TEST(ComposeParity, MatchesStudioComposeIconByteForByte) {
    auto lib = Library::load(fs::path(ROADOS_ASSETS_DIR) / "rvhl");
    ASSERT_TRUE(lib) << lib.error().message;
    const json golden = readJson(fs::path(ROADOS_FIXTURES_DIR) / "rvhl-golden" / "compose.json");
    ASSERT_EQ(golden["studioCommit"].get<std::string>(), lib->info().studioCommit)
        << "golden vectors were generated from a different Studio commit; run scripts/export_rvhl.sh --golden";

    int checked = 0, mismatches = 0;
    for (const auto& c : golden["cases"]) {
        const std::string name = c["name"].get<std::string>();
        const Entry* e = lib->find(c["entry"].get<std::string>());
        ASSERT_NE(e, nullptr) << name;
        auto r = compose(*lib, *e, toOptions(c["options"]));
        ASSERT_TRUE(r) << name << ": " << r.error().message;
        const std::string expected = c["svg"].get<std::string>();
        EXPECT_EQ(toString(r->frame), c["frame"].get<std::string>()) << name;
        if (r->svg != expected) {
            if (++mismatches <= 5) {
                std::size_t i = 0;
                while (i < expected.size() && i < r->svg.size() && expected[i] == r->svg[i]) ++i;
                const std::size_t from = i > 60 ? i - 60 : 0;
                ADD_FAILURE() << name << " differs at byte " << i << "\n  studio: …" << expected.substr(from, 140)
                              << "\n  c++:    …" << r->svg.substr(from, 140);
            }
        }
        ++checked;
    }
    EXPECT_EQ(mismatches, 0) << mismatches << " of " << checked << " cases differ";
    EXPECT_GT(checked, 1000);
}

TEST(Compose, LayersCanBeDisabledAndReordered) {
    auto lib = Library::load(fs::path(ROADOS_ASSETS_DIR) / "rvhl");
    ASSERT_TRUE(lib);
    const Entry& e = *lib->find("RDM-003");

    HazardOptions o;
    o.distanceM = 150;
    o.count = 2;
    auto full = compose(*lib, e, o);
    ASSERT_TRUE(full);
    EXPECT_EQ(full->drawn, (std::vector<Layer>{Layer::Frame, Layer::Pictogram, Layer::SeverityCode, Layer::Count, Layer::Distance}));

    o.disable(Layer::SeverityCode).disable(Layer::Frame);
    auto bare = compose(*lib, e, o);
    ASSERT_TRUE(bare);
    EXPECT_EQ(bare->drawn, (std::vector<Layer>{Layer::Pictogram, Layer::Count, Layer::Distance}));
    EXPECT_EQ(bare->svg.find(">S3<"), std::string::npos);

    o.enable(Layer::Frame);
    EXPECT_EQ(o.layers[1], Layer::Frame);  // restored to its default position

    o.layers = {Layer::Distance, Layer::Pictogram};
    auto reordered = compose(*lib, e, o);
    ASSERT_TRUE(reordered);
    EXPECT_EQ(reordered->drawn, (std::vector<Layer>{Layer::Distance, Layer::Pictogram}));
    EXPECT_LT(reordered->svg.find("150 m"), reordered->svg.find("<g transform=\"translate(31.00"));
}

TEST(Compose, FormatsDistancesLikeTheStudio) {
    EXPECT_EQ(formatDistance(0), "0 m");
    EXPECT_EQ(formatDistance(155), "160 m");
    EXPECT_EQ(formatDistance(1500), "1.5 km");
    EXPECT_EQ(formatDistance(12345), "12 km");
    EXPECT_EQ(formatDistance(90, UnitSystem::Imperial), "300 ft");
    EXPECT_EQ(formatDistance(25000, UnitSystem::Imperial), "16 mi");
}
